(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.015+t*0.3)*12;
  const w2x = Math.sin(x*0.009-t*0.15)*25 + Math.cos(y*0.007+t*0.12)*20;
  const w2y = Math.cos(y*0.01+t*0.17)*25 + Math.sin(x*0.008-t*0.2)*20;
  const sx = x + w1x + w2x*0.5, sy = y + w1y + w2y*0.5;
  const src = [
    [140+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*45, 0.075, 2.1, 1.0],
    [340+Math.cos(t*0.45)*100, 150+Math.sin(t*0.6)*55, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.28+2)*130, 110+Math.cos(t*0.42+1)*80, 0.055, 2.5, 1.1],
    [80+Math.cos(t*0.7+1)*70, 190+Math.sin(t*0.5+3)*55, 0.11, 1.6, 0.85],
    [380+Math.sin(t*0.38+4)*80, 50+Math.cos(t*0.75+2)*65, 0.065, 2.8, 1.05],
    [200+Math.cos(t*0.32+5)*100, 210+Math.sin(t*0.48)*70, 0.085, 2.0, 0.95],
    [300+Math.sin(t*0.55+3)*90, 180+Math.cos(t*0.33+4)*50, 0.07, 2.3, 1.0],
    [100+Math.cos(t*0.42+2)*85, 100+Math.sin(t*0.58+1)*60, 0.095, 1.7, 0.88],
    [400+Math.sin(t*0.3+1)*60, 200+Math.cos(t*0.5+3)*40, 0.06, 3.0, 1.15],
    [180+Math.cos(t*0.62)*75, 30+Math.sin(t*0.4+2)*35, 0.1, 1.5, 0.82]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wf = Math.sin(d*0.08+t*0.5)*0.15+1;
    aS += (Math.sin(d*f*wf-t*sp)+Math.sin(d*f*1.618-t*sp*0.7)*0.5)*w;
    iS += (Math.sin(d*f*0.618*wf+t*sp*0.55+1.5)+Math.cos(d*f*0.382+t*sp*0.3)*0.4)*w;
    cS += Math.sin(d*f*0.3+t*sp*0.8+2.1)*w*0.3;
  }
  const n = 10;
  const act=aS/n, inh=iS/n, cor=cS/n;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*1.0))/2
    + Math.sin((sx+sy)*0.11+t*2.2)*0.25 + Math.sin((sx-sy)*0.09-t*1.8)*0.25
    + Math.sin(sx*0.06+sy*0.04-t*1.5)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
