      const vy = 40+((i*53)%200)+Math.cos(t*0.35+i*2.1)*25;
      const d = Math.sqrt((sx-vx)**2+(sy-vy)**2);
      if (d < md) { md2 = md; md = d; } else if (d < md2) { md2 = d; }
    }
    return Math.sin((md2-md)*0.3-t)*0.3;
  })();
  const reaction = Math.tanh((act - inh*0.65 + cor*0.3 + bg*0.28 + spiral + voronoi)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.45
    +Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.4)*0.28;
  const fine = Math.sin(sx*0.35+t*3)*Math.sin(sy*0.35-t*2.5)*0.08;
