  const v = blend*0.5+0.5;
  const glow = Math.max(0, Math.abs(reaction)-0.6)*2.5;
  const pal = [
    [6,12,52],[12,42,88],[18,78,118],[24,118,128],[50,155,120],
    [120,178,85],[195,185,60],[215,155,55],[210,110,65],[185,65,75],
    [130,35,65],[70,18,55],[30,10,48],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const cr = pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const cg = pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const cb = pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum = 0.78 + Math.sin(reaction*Math.PI)*0.22;
  const edge = Math.abs(reaction)>0.72 ? 1.18 : 1.0;
  const gr = glow*0.4;
  return [
    Math.min(255, (cr*lum*edge + gr*60)|0),
    Math.min(255, (cg*lum*edge + gr*40)|0),
    Math.min(255, (cb*lum*edge + gr*30)|0)
  ];
}
